<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { ApiError, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import { governanceActions, governanceActionLabels, governanceCanEdit, governanceDraft, governanceFields, governanceIDs, governanceKinds, governancePayload, governanceSourceURL, governanceStatuses, kindReceiptPurposes, receiptLabels, type GovernanceCatalog, type GovernanceDraft, type GovernanceEvidence, type GovernanceHistory, type GovernanceKind, type GovernancePage, type GovernanceRecord } from './governance-operations'
import './ai-security.css'
import './governance-operations.css'

const props=defineProps<{workspace:Workspace;initialKind?:string;initialRecordId?:string|number}>()
const emit=defineEmits<{sessionExpired:[]}>()
const base=workspacePath(props.workspace.slug)+'/governance-ops'
const home='#/'+encodeURIComponent(props.workspace.slug)
const controller=new AbortController()
const canWrite=computed(()=>['owner','operator'].includes(props.workspace.role))
const kind=ref<GovernanceKind>(props.initialKind && props.initialKind in governanceKinds?props.initialKind as GovernanceKind:'rights_request')
const status=ref(''),appliedStatus=ref('')
const catalog=ref<GovernanceCatalog|null>(null),page=ref<GovernancePage<GovernanceRecord>|null>(null)
const cursor=ref(''),cursors=ref<string[]>([]),loading=ref(false),catalogLoading=ref(false),detailLoading=ref(false)
const error=ref(''),listError=ref(''),catalogError=ref(''),feedback=ref(''),busy=ref('')
const selected=ref<GovernanceRecord|null>(null),mode=ref<'view'|'edit'|'create'>('view')
const draft=ref<GovernanceDraft>(governanceDraft(kind.value)),savedDraft=ref(''),note=ref('')
const dirty=computed(()=>mode.value!=='view' && JSON.stringify(draft.value)!==savedDraft.value)
const actions=computed(()=>selected.value?governanceActions(selected.value,props.workspace.role):[])
const editor=ref<HTMLElement|null>(null),detailHeading=ref<HTMLElement|null>(null)
const checkLookup=ref(''),checkLoading=ref(false),checkError=ref(''),checkEvidence=ref<GovernanceEvidence[]>([]),loadedCheck=ref(0)
const historyItems=ref<GovernanceHistory[]>([]),historyCursor=ref(''),historyCursors=ref<string[]>([]),historyNext=ref(''),historyHasMore=ref(false),historyLoading=ref(false),historyError=ref('')
let listGeneration=0,detailGeneration=0
const completionHints:Record<GovernanceKind,string>={rights_request:'核验申请身份，记录答复和送达证据；删除请求还需核对涉及系统或保留例外。',consent:'取得同意须有告知版本与同意证据；撤回须逐系统关联传播回执。',vendor:'明确处理关系、跨境与合同，关联实际监督检查。合同到期不代表数据已返还或删除。',audit:'核对机构及关联方、负责人、独立性与报告；人数口径必须有证据，审计计划不等于完成。',incident:'核定事件分级、主体和实际渠道，逐渠道分别保留初报和总结依据。',labeling:'逐模态核对实际内容摘要、显式与隐式标识、导出保留及验证证据。格式未支持时保留未知。'}
function fail(cause:unknown,target=error){
  if(controller.signal.aborted)return
  if(cause instanceof ApiError && cause.status===401)emit('sessionExpired')
  target.value=describeError(cause)
  if(cause instanceof ApiError && cause.status===409)target.value+=' 当前草稿与办理意见已保留。请载入最新记录后核对修订；本次未覆盖其他成员的修改。'
}
async function loadCatalog(){
  catalogLoading.value=true;catalogError.value=''
  try{catalog.value=await request<GovernanceCatalog>(base+'/catalog',{signal:controller.signal})}catch(cause){fail(cause,catalogError)}finally{catalogLoading.value=false}
}
async function loadPage(nextCursor:string|number='',remember=false,nextStatus=appliedStatus.value){
  const generation=++listGeneration
  loading.value=true;listError.value=''
  const query=new URLSearchParams({kind:kind.value,limit:'50'})
  if(nextStatus)query.set('status',nextStatus)
  if(nextCursor)query.set('cursor',String(nextCursor))
  try{
    const next=await request<GovernancePage<GovernanceRecord>>(base+'/records?'+query,{signal:controller.signal})
    if(controller.signal.aborted || generation!==listGeneration)return
    if(remember)cursors.value.push(cursor.value);else if(!nextCursor)cursors.value=[]
    page.value={...next,items:next.items || []};cursor.value=String(nextCursor);appliedStatus.value=nextStatus
    return true
  }catch(cause){if(generation===listGeneration)fail(cause,listError)}finally{if(generation===listGeneration)loading.value=false}
}
async function changeKind(next:GovernanceKind){
  if(loading.value || dirty.value)return
  kind.value=next;status.value='';appliedStatus.value='';page.value=null;cursors.value=[];cursor.value='';selected.value=null;mode.value='view';detailGeneration++
  await loadPage()
}
async function previousPage(){const previous=cursors.value.at(-1);if(previous!==undefined && await loadPage(previous))cursors.value.pop()}
function applyRecord(record:GovernanceRecord){
  selected.value=record;draft.value=governanceDraft(record.kind,record);savedDraft.value=JSON.stringify(draft.value)
  mode.value='view';note.value='';checkEvidence.value=[];checkError.value='';loadedCheck.value=0
  historyItems.value=record.history || [];historyCursor.value='';historyCursors.value=[];historyNext.value=String(record.historyNextCursor || '');historyHasMore.value=record.historyHasMore;historyError.value=''
}
async function selectRecord(id:number){
  if(!Number.isSafeInteger(id) || id<1)return
  const generation=++detailGeneration
  detailLoading.value=true;error.value=''
  try{const record=await request<GovernanceRecord>(base+'/records/'+id,{signal:controller.signal});if(controller.signal.aborted || generation!==detailGeneration)return;applyRecord(record);detailHeading.value?.focus({preventScroll:true})}catch(cause){if(generation===detailGeneration)fail(cause)}finally{if(generation===detailGeneration)detailLoading.value=false}
}
function focusEditor(){requestAnimationFrame(()=>{editor.value?.scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});editor.value?.querySelector<HTMLInputElement>('input')?.focus({preventScroll:true})})}
function createRecord(){
  detailGeneration++;selected.value=null;mode.value='create';draft.value=governanceDraft(kind.value);savedDraft.value=JSON.stringify(draft.value)
  checkEvidence.value=[];checkError.value='';loadedCheck.value=0;error.value='';feedback.value='';focusEditor()
}
function editRecord(){if(!selected.value || !governanceCanEdit(selected.value,props.workspace.role))return;draft.value=governanceDraft(selected.value.kind,selected.value);savedDraft.value=JSON.stringify(draft.value);mode.value='edit';focusEditor()}
function cancelEdit(){mode.value='view';if(selected.value)draft.value=governanceDraft(selected.value.kind,selected.value);error.value='';checkError.value=''}
async function save(){
  if(!canWrite.value || busy.value || !catalog.value)return
  let payload:ReturnType<typeof governancePayload>
  try{payload=governancePayload(draft.value)}catch(cause){error.value=cause instanceof Error?cause.message:'请核对办理字段。';return}
  busy.value='save';error.value='';feedback.value=''
  const id=mode.value==='edit'?selected.value?.id:undefined
  try{const record=await request<GovernanceRecord>(base+'/records'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(payload),signal:controller.signal});applyRecord(record);feedback.value='办理记录已保存，尚未替代实际处理或独立复核。';await loadPage()}catch(cause){fail(cause)}finally{busy.value=''}
}
async function act(action:string){
  if(!selected.value || busy.value || !note.value.trim() || !actions.value.includes(action))return
  busy.value=action;error.value='';feedback.value=''
  try{const record=await request<GovernanceRecord>(base+'/records/'+selected.value.id+'/actions',{method:'POST',body:JSON.stringify({revision:selected.value.revision,action,note:note.value.trim()}),signal:controller.signal});applyRecord(record);feedback.value='已记录“'+governanceActionLabels[action]+'”。请继续核对实际系统处理和来源回执。';await loadPage()}catch(cause){fail(cause)}finally{busy.value=''}
}
async function loadHistory(nextCursor:string|number='',remember=false){
  if(!selected.value || historyLoading.value)return
  const id=selected.value.id,generation=detailGeneration
  historyLoading.value=true;historyError.value=''
  try{const out=await request<GovernancePage<GovernanceHistory>>(base+'/records/'+id+'/history?limit=50'+(nextCursor?'&cursor='+encodeURIComponent(nextCursor):''),{signal:controller.signal});if(controller.signal.aborted || generation!==detailGeneration || selected.value?.id!==id)return;if(remember)historyCursors.value.push(historyCursor.value);else if(!nextCursor)historyCursors.value=[];historyItems.value=out.items || [];historyCursor.value=String(nextCursor);historyNext.value=String(out.nextCursor || '');historyHasMore.value=out.hasMore;return true}catch(cause){if(generation===detailGeneration)fail(cause,historyError)}finally{historyLoading.value=false}
}
async function previousHistory(){const previous=historyCursors.value.at(-1);if(previous!==undefined && await loadHistory(previous))historyCursors.value.pop()}
async function lookupEvidence(){
  if(checkLoading.value)return
  let ids:number[]
  try{ids=governanceIDs(checkLookup.value);if(ids.length!==1)throw new Error('请输入一条真实检查编号。')}catch(cause){checkError.value=cause instanceof Error?cause.message:'检查编号无效。';return}
  checkLoading.value=true;checkError.value='';checkEvidence.value=[];loadedCheck.value=0
  const version=JSON.stringify({kind:draft.value.kind,revision:draft.value.revision}),generation=detailGeneration
  try{const detail=await request<{id:number;evidence:GovernanceEvidence[]}>(workspacePath(props.workspace.slug)+'/checks/'+ids[0],{signal:controller.signal});if(controller.signal.aborted || generation!==detailGeneration || mode.value==='view' || version!==JSON.stringify({kind:draft.value.kind,revision:draft.value.revision}))return;loadedCheck.value=ids[0]!;checkEvidence.value=(detail.evidence || []).map(item=>({...item,checkId:ids[0]!}))}catch(cause){fail(cause,checkError)}finally{checkLoading.value=false}
}
function selectedEvidence(id:number){try{return governanceIDs(draft.value.evidenceIds).includes(id)}catch{return false}}
function toggleEvidence(item:GovernanceEvidence,checked:boolean){
  try{const evidence=governanceIDs(draft.value.evidenceIds);draft.value.evidenceIds=(checked?[...new Set([...evidence,item.id])]:evidence.filter(id=>id!==item.id)).join(', ');if(checked)draft.value.checkIds=[...new Set([...governanceIDs(draft.value.checkIds),item.checkId])].join(', ')}catch(cause){fail(cause,checkError)}
}
const receiptEvidence=computed(()=>{try{return governanceIDs(draft.value.evidenceIds)}catch{return []}})
function fieldValue(record:GovernanceRecord,key:string){const value=record.details[key];const field=governanceFields[record.kind].find(item=>item.key===key);if(value===undefined || value===null || value==='')return '尚未登记';if(field?.type==='checkbox')return value?'是':'否';if(Array.isArray(value))return value.length?value.join('、'):'尚未登记';if(field?.options)return field.options[String(value)] || String(value);if(field?.type==='date')return formatDate(String(value));return String(value)}
function evidenceName(id:number){return checkEvidence.value.find(item=>item.id===id)?.summary || selected.value?.evidence?.find(item=>item.id===id)?.summary || '真实检查证据'}
const deadlineLabels:Record<string,string>={upcoming:'未到计划时点',overdue:'计划时点已过',pending_scope:'适用范围待核定',pending_calendar:'等待适用工作日历'}
onMounted(()=>{void loadCatalog();void loadPage();const id=Number(props.initialRecordId);if(Number.isSafeInteger(id) && id>0)void selectRecord(id)})
onUnmounted(()=>controller.abort())
</script>

<template>
  <section class="ai-security-workspace governance-operations" :aria-busy="!!busy || detailLoading">
    <header class="page-header"><div><p class="eyebrow">数据治理 / 办理与独立复核</p><h1>治理办理</h1><p>将隐私、供应商与监管事项落实到责任人、真实证据、适用依据和办理记录。</p></div><div class="page-actions"><button class="button button-secondary" :disabled="loading || !!busy" @click="loadPage()">刷新当前台账</button><button v-if="canWrite" class="button button-primary" :disabled="!!busy || dirty || detailLoading || !catalog" @click="createRecord">新建{{ governanceKinds[kind] }}</button></div></header>
    <p v-if="error" class="message message-error" role="alert">{{ error }}</p><p v-if="feedback" class="message message-success" role="status">{{ feedback }}</p>
    <p v-if="catalogLoading" class="message" role="status">正在载入办理种类与法规版本…</p><p v-if="catalogError" class="message message-error" role="alert">{{ catalogError }}<button class="button button-secondary" @click="loadCatalog">重试法规目录</button></p>
    <nav class="governance-kind-nav" aria-label="治理办理种类"><button v-for="(label,key) in governanceKinds" :key="key" type="button" :aria-pressed="kind===key" :disabled="loading || dirty || !!busy" @click="changeKind(key)"><span>{{ label }}</span><small>{{ key==='rights_request'?'身份、答复与送达':key==='consent'?'告知、同意与撤回':key==='vendor'?'合同、监督与转委托':key==='audit'?'范围、独立性与报告':key==='incident'?'分级、报送与时限':'模态、验证与导出' }}</small></button></nav>
    <p v-if="dirty" class="message message-warning" role="status">有未保存的{{ mode==='create'?'新建':'编辑' }}草稿。保存或取消编辑后可切换办理种类和记录。</p>
    <section class="panel"><div class="ai-security-heading"><div><h2>{{ governanceKinds[kind] }}台账</h2><p>{{ completionHints[kind] }}</p></div><a :href="home+'/checks'">进入真实检查与证据</a></div>
      <form class="ai-security-filter" @submit.prevent="loadPage('',false,status)"><label class="field">办理状态<select v-model="status" :disabled="loading"><option value="">全部状态</option><option v-for="(label,key) in governanceStatuses" :key="key" :value="key">{{ label }}</option></select></label><button class="button button-secondary" :disabled="loading">查询台账</button><span class="table-secondary">应用状态：{{ governanceStatuses[appliedStatus] || '全部' }} · 每页最多 50 条</span></form>
      <p v-if="listError" class="message message-error" role="alert">{{ listError }}{{ page?' 下方保留上次成功载入的台账。':'' }}</p><p v-if="loading" class="ai-security-body" role="status">正在读取办理台账…</p>
      <div v-if="page?.items.length" class="table-scroll" role="region" aria-label="治理办理台账" tabindex="0"><table class="data-table governance-records"><thead><tr><th scope="col">事项与责任人</th><th scope="col">状态与适用判断</th><th scope="col">证据范围</th><th scope="col">更新时间</th></tr></thead><tbody><tr v-for="item in page.items" :key="item.id" :class="{'is-selected':selected?.id===item.id}"><th scope="row"><button class="governance-record-link" :aria-pressed="selected?.id===item.id" :disabled="detailLoading || dirty || !!busy" @click="selectRecord(item.id)">{{ item.title }}</button><span class="table-secondary">#{{ item.id }} · {{ item.owner }}</span></th><td><span class="badge" :class="item.status==='completed' || item.status==='withdrawn'?'status-verified':item.status==='needs_work'?'status-needs-work':'status-draft'">{{ governanceStatuses[item.status] || item.status }}</span><span class="table-secondary">{{ item.applicability==='applicable'?'已判断适用':item.applicability==='not_applicable'?'已判断不适用':'适用性待核定' }}</span></td><td>{{ item.evidenceIds?.length || 0 }} 项证据 · {{ item.checkIds?.length || 0 }} 项检查<span class="table-secondary">修订 {{ item.revision }} · {{ item.regulationIds?.length || 0 }} 项依据</span></td><td>{{ formatDate(item.updatedAt) }}</td></tr></tbody></table></div>
      <div v-else-if="!loading && !listError" class="ai-security-empty"><h3>当前范围没有办理记录</h3><p>确认筛选条件后，可从一项真实业务事项开始登记；空台账不表示已满足相关义务。</p><button v-if="canWrite" class="button button-secondary" :disabled="!catalog || dirty" @click="createRecord">登记首项办理</button></div>
      <div v-if="page" class="ai-security-pagination"><button class="button button-secondary" :disabled="loading || !cursors.length" @click="previousPage">较新一页</button><button class="button button-secondary" :disabled="loading || !page.hasMore || !page.nextCursor" @click="loadPage(page.nextCursor,true)">较早一页</button><p>第 {{ cursors.length+1 }} 页 · 本页 {{ page.items.length }} 条 · {{ page.hasMore?'仍有较早事项':'当前范围已到最早事项' }}</p></div>
    </section>
    <p v-if="detailLoading" class="message" role="status">正在载入办理详情与冻结依据…</p>
    <ul v-if="selected?.evidenceIssues?.length" class="message message-warning governance-evidence-issues" role="status"><li v-for="issue in selected.evidenceIssues" :key="issue">{{ issue }}</li></ul>
    <template v-if="selected && mode==='view'">
      <div class="governance-detail-layout"><section class="panel"><div class="ai-security-heading"><div><p class="eyebrow">{{ governanceKinds[selected.kind] }} · #{{ selected.id }}</p><h2 ref="detailHeading" tabindex="-1">{{ selected.title }}</h2><p>{{ selected.owner }} · 修订 {{ selected.revision }} · {{ governanceStatuses[selected.status] || selected.status }}</p></div><div class="page-actions"><button class="button button-secondary" :disabled="!!busy || detailLoading" @click="selectRecord(selected.id)">载入最新详情</button><button v-if="governanceCanEdit(selected,workspace.role)" class="button button-primary" :disabled="!!busy || detailLoading" @click="editRecord">编辑办理内容</button></div></div>
        <div class="ai-security-body"><dl class="ai-security-facts"><div><dt>适用判断</dt><dd>{{ selected.applicability==='applicable'?'适用':selected.applicability==='not_applicable'?'不适用':'待核定' }}</dd></div><div><dt>关联活动</dt><dd><a v-if="selected.activityId" :href="home+'/activities/'+selected.activityId">活动 #{{ selected.activityId }}</a><span v-else>未关联</span></dd></div><div class="governance-fact-wide"><dt>判断依据</dt><dd>{{ selected.applicabilityReason }}</dd></div><div v-for="field in governanceFields[selected.kind]" :key="field.key"><dt>{{ field.label }}</dt><dd>{{ fieldValue(selected,field.key) }}</dd></div></dl><div v-if="selected.checkIds?.length" class="ai-security-links governance-check-links"><a v-for="id in selected.checkIds" :key="id" :href="home+'/checks/'+id">检查 #{{ id }}</a></div></div>
        <div v-if="actions.length" class="ai-security-body"><h3>推进办理与独立复核</h3><p class="table-secondary">负责人或复核人独立复核，所有历史贡献者须回避；最终权限由服务端校验。意见与本修订一同留痕。</p><label class="field">本次办理或复核意见<textarea v-model.trim="note" rows="3" maxlength="600" :disabled="!!busy" placeholder="填写已核对的范围、结论与依据，不填写个人信息或秘密"></textarea></label><div class="ai-security-actions"><button v-for="action in actions" :key="action" class="button" :class="['approve','submit','start'].includes(action)?'button-primary':'button-secondary'" :disabled="!!busy || !note.trim() || detailLoading" @click="act(action)">{{ busy===action?'正在记录…':governanceActionLabels[action] }}</button></div></div>
        <p v-else class="ai-security-body table-secondary">{{ selected.status==='in_review'?'等待独立复核人处理。':'本状态下当前账号没有可执行的办理动作。' }}</p>
      </section><aside class="panel governance-deadlines"><div class="ai-security-heading"><div><h2>期限与待核定项</h2><p>基于本次冻结依据与登记事实计算。</p></div></div><div v-if="selected.deadlines?.length" class="ai-security-body"><article v-for="deadline in selected.deadlines" :key="deadline.code" class="governance-deadline"><span class="badge" :class="deadline.status==='overdue'?'status-needs-work':'status-draft'">{{ deadlineLabels[deadline.status] || deadline.status }}</span><h3>{{ deadline.title }}</h3><p class="governance-due">{{ deadline.dueAt?formatDate(deadline.dueAt):'尚无可确认的截止时点' }}</p><p v-if="deadline.amount && deadline.unit==='working_days'">{{ deadline.amount }} 个工作日，等待适用的版本化日历。</p><p>{{ deadline.reason }}</p><small>{{ deadline.receiptPresent?'已有对应证据引用，实际送达与收件仍需核对':'未关联对应用途的回执证据' }}</small></article></div><p v-else class="ai-security-empty">当前字段与适用判断未产生可列示期限。请核对适用范围；这不表示没有实际义务。</p></aside></div>
      <section class="panel"><div class="ai-security-heading"><div><h2>本修订冻结的证据与用途回执</h2><p>保留证据来源属性和登记时点；引用不自动改变源系统或证明送达。</p></div></div><div v-if="selected.evidence?.length" class="table-scroll" role="region" aria-label="冻结的真实证据" tabindex="0"><table class="data-table governance-evidence"><thead><tr><th scope="col">证据与检查</th><th scope="col">观察内容</th><th scope="col">原始来源</th><th scope="col">用途回执关联</th></tr></thead><tbody><tr v-for="item in selected.evidence" :key="item.id"><th scope="row">证据 #{{ item.id }}<span class="table-secondary"><a :href="home+'/checks/'+item.checkId">检查 #{{ item.checkId }}</a> · {{ item.kind }}</span></th><td>{{ item.summary }}<span class="table-secondary">观察 {{ formatDate(item.observedAt) }}</span></td><td>{{ item.sourceSystem }}<span class="table-secondary">{{ item.sourceRecord }}</span><details v-if="item.snapshotDigest"><summary>核对冻结摘要</summary><p class="mono table-secondary">{{ item.snapshotDigest }}</p></details></td><td><p v-for="(receipt,index) in selected.receipts?.filter(receipt=>receipt.evidenceId===item.id)" :key="index">{{ receiptLabels[receipt.purpose] || receipt.purpose }}<span v-if="receipt.system" class="table-secondary">系统 / 渠道：{{ receipt.system }}</span></p><span v-if="!selected.receipts?.some(receipt=>receipt.evidenceId===item.id)">仅作关联证据</span></td></tr></tbody></table></div><p v-else class="ai-security-empty">当前修订尚未冻结真实检查证据，仍需补充后提交复核。</p></section>
      <section class="panel"><div class="ai-security-heading"><div><h2>采用的法规与标准版本</h2><p>以下为本次办理冻结的版本与适用边界；目录更新不会改写历史依据。</p></div></div><div class="governance-regulations ai-security-body"><article v-for="regulation in selected.regulations || []" :key="regulation.id"><h3><a v-if="governanceSourceURL(regulation.sourceUrl)" :href="governanceSourceURL(regulation.sourceUrl)" target="_blank" rel="noopener noreferrer">{{ regulation.title }} <span class="sr-only">（新窗口）</span></a><span v-else>{{ regulation.title }}</span></h3><p>版本 {{ regulation.version }} · 生效 {{ regulation.effective }}</p><p>{{ regulation.scope }}</p><p class="table-secondary">{{ regulation.boundary }}</p></article><p v-if="!selected.regulations?.length" class="table-secondary">尚未采用明确法规版本。</p></div></section>
      <section class="panel"><div class="ai-security-heading"><div><h2>办理与独立复核历史</h2><p>每次变更均保留操作者、修订和快照摘要。当前状态不能覆盖历史判断。</p></div><button class="button button-secondary" :disabled="historyLoading" @click="loadHistory()">返回最新历史</button></div><p v-if="historyError" class="message message-error" role="alert">{{ historyError }}</p><p v-if="historyLoading" class="ai-security-body" role="status">正在读取历史…</p><ol v-if="historyItems.length" class="governance-history"><li v-for="entry in historyItems" :key="entry.id"><div><strong>{{ governanceActionLabels[entry.action] || ({create:'创建记录',update:'更新内容'} as Record<string,string>)[entry.action] || entry.action }}</strong><span class="table-secondary">{{ entry.actor || '成员 #'+entry.actorId }} · {{ formatDate(entry.createdAt) }} · 修订 {{ entry.revision }}</span></div><p>{{ entry.note || '未附加意见' }}</p><details><summary>查看快照摘要</summary><p class="mono table-secondary">{{ entry.snapshotDigest }}</p></details></li></ol><p v-else-if="!historyLoading" class="ai-security-empty">尚无可读取的历史记录。</p><div class="ai-security-pagination"><button class="button button-secondary" :disabled="historyLoading || !historyCursors.length" @click="previousHistory">较新一页</button><button class="button button-secondary" :disabled="historyLoading || !historyHasMore || !historyNext" @click="loadHistory(historyNext,true)">较早一页</button><p>第 {{ historyCursors.length+1 }} 页 · 本页 {{ historyItems.length }} 条</p></div></section>
      <p class="ai-security-note">{{ selected.boundary || catalog?.boundary }}</p>
    </template>
    <form v-if="mode!=='view' && canWrite" ref="editor" class="panel governance-editor" @submit.prevent="save"><div class="ai-security-heading"><div><p class="eyebrow">{{ mode==='create'?'新建办理':'修订办理 #'+selected?.id }}</p><h2>{{ governanceKinds[draft.kind] }}</h2><p>{{ completionHints[draft.kind] }}</p></div><button class="button button-secondary" type="button" :disabled="!!busy" @click="cancelEdit">{{ dirty?'取消并丢弃草稿':'关闭编辑' }}</button></div>
      <div class="ai-security-body"><fieldset class="ai-security-fields" :disabled="!!busy || !catalog"><legend class="sr-only">办理事项与适用性</legend><label class="field">事项标题<input v-model.trim="draft.title" required maxlength="120"></label><label class="field">责任人或团队<input v-model.trim="draft.owner" required maxlength="100"></label><label class="field">本工作区处理活动编号（可选）<input v-model.trim="draft.activityId" type="text" pattern="[0-9]+" maxlength="20" inputmode="numeric"></label><label class="field">适用性判断<select v-model="draft.applicability" required :disabled="!!selected?.withdrawing"><option value="unknown">待核定</option><option value="applicable">适用</option><option value="not_applicable">不适用</option></select></label><label class="field field-wide">适用或不适用的事实与理由<textarea v-model.trim="draft.applicabilityReason" required rows="3" maxlength="600"></textarea><small>说明实际服务角色、地域、处理范围及判断依据；待核定事项不能直接完成复核。</small></label></fieldset></div>
      <div class="ai-security-body"><h3>业务事实</h3><p v-if="selected?.withdrawing" class="ai-security-note">撤回阶段保留原同意主体、目的、依据、告知版本与取得时间；原涉及系统不能移除。请补充真实撤回时间和逐系统传播回执。</p><fieldset class="ai-security-fields" :disabled="!!busy || !catalog"><legend class="sr-only">{{ governanceKinds[draft.kind] }}业务事实</legend><template v-for="field in governanceFields[draft.kind]" :key="field.key"><label v-if="field.type==='checkbox'" class="ai-security-toggle field-wide"><input v-model="draft.details[field.key]" type="checkbox">{{ field.label }}<small v-if="field.help">{{ field.help }}</small></label><label v-else class="field" :class="{'field-wide':['textarea','list'].includes(field.type || '')}"><span>{{ field.label }}<span v-if="field.required" aria-hidden="true"> *</span></span><select v-if="field.type==='select'" :value="String(draft.details[field.key] ?? '')" @change="draft.details[field.key]=($event.target as HTMLSelectElement).value" :required="field.required"><option v-for="(label,value) in field.options" :key="value" :value="value">{{ label }}</option></select><textarea v-else-if="field.type==='textarea' || field.type==='list'" :value="String(draft.details[field.key] ?? '')" @input="draft.details[field.key]=($event.target as HTMLTextAreaElement).value" :required="field.required" :readonly="selected?.withdrawing && ['subjectRef','purpose','lawfulBasis','noticeVersion','grantedAt','withdrawalAt'].includes(field.key)" :maxlength="field.type==='list'?3300:600" rows="3"></textarea><input v-else :value="String(draft.details[field.key] ?? '')" @input="draft.details[field.key]=($event.target as HTMLInputElement).value" :type="field.type==='number'?'number':'text'" :required="field.required" :readonly="selected?.withdrawing && ['subjectRef','purpose','lawfulBasis','noticeVersion','grantedAt','withdrawalAt'].includes(field.key)" :min="field.type==='number'?0:undefined" :max="field.max" :step="field.type==='number'?1:undefined" :maxlength="field.type==='date'?40:field.key==='subjectRef' || field.key==='artifactDigest'?64:160" :placeholder="field.type==='date'?'YYYY-MM-DDTHH:mm:ss+08:00':undefined" :spellcheck="field.type==='date' || field.key==='subjectRef' || field.key==='artifactDigest'?false:undefined"><small v-if="field.help">{{ field.help }}</small><small v-else-if="field.type==='list'">每行一项，最多 20 项；填写系统或渠道引用，不填敏感正文。</small><small v-else-if="field.type==='date'">填写真实时间和时区。留空表示尚未登记，不用预计时间替代已经发生的事实。</small></label></template></fieldset></div>
      <div class="ai-security-body"><h3>适用依据与版本</h3><p class="table-secondary">按实际业务逐项选择。引用法规不表示已满足全部要求。</p><div class="governance-regulation-picker"><label v-for="regulation in catalog?.regulations || []" :key="regulation.id" class="governance-regulation-choice"><input v-model="draft.regulationIds" type="checkbox" :value="regulation.id" :disabled="!!busy"><span><strong>{{ regulation.title }}</strong><small>版本 {{ regulation.version }} · 生效 {{ regulation.effective }}</small><small>{{ regulation.scope }}</small></span></label></div></div>
      <div class="ai-security-body"><h3>真实检查与证据</h3><div class="ai-security-fields"><label class="field">关联检查编号<textarea v-model="draft.checkIds" rows="2" :disabled="!!busy" placeholder="多个编号用逗号分隔"></textarea></label><label class="field">关联证据编号<textarea v-model="draft.evidenceIds" rows="2" :disabled="!!busy" placeholder="当前工作区检查中的真实证据"></textarea></label></div><p class="table-secondary">编号由服务端校验工作区、检查范围和真实证据归属。可先读取一项检查，再勾选所需证据。</p><div class="governance-lookup"><label class="field">读取检查编号<input v-model.trim="checkLookup" type="text" pattern="[0-9]+" maxlength="20" inputmode="numeric" :disabled="checkLoading || !!busy"></label><button class="button button-secondary" type="button" :disabled="checkLoading || !!busy || !checkLookup" @click="lookupEvidence">{{ checkLoading?'正在读取…':'读取真实证据' }}</button><a :href="home+'/checks'">前往检查台账</a></div><p v-if="checkError" class="message message-error" role="alert">{{ checkError }}</p><div v-if="checkEvidence.length" class="governance-evidence-picker"><label v-for="item in checkEvidence" :key="item.id"><input type="checkbox" :checked="selectedEvidence(item.id)" :disabled="!!busy" @change="toggleEvidence(item,($event.target as HTMLInputElement).checked)"><span><strong>证据 #{{ item.id }} · {{ item.kind }}</strong><span>{{ item.summary }}</span><small>{{ item.sourceSystem }} · {{ formatDate(item.observedAt) }}</small></span></label></div><p v-else-if="loadedCheck && !checkLoading" class="table-secondary">检查 #{{ loadedCheck }} 尚无证据。请在原检查中登记或取得真实观察后继续。</p></div>
      <div class="ai-security-body"><h3>证据用途与系统 / 渠道</h3><p class="table-secondary">为已关联证据指定真实用途。同意撤回按系统、事件报告按渠道分别绑定；证据引用不等于已执行或已收件。</p><div v-for="(receipt,index) in draft.receipts" :key="index" class="governance-receipt-row"><label class="field">用途<select v-model="receipt.purpose" :disabled="!!busy"><option v-for="purpose in kindReceiptPurposes[draft.kind]" :key="purpose" :value="purpose">{{ receiptLabels[purpose] }}</option></select></label><label class="field">真实证据<select v-model.number="receipt.evidenceId" required :disabled="!!busy"><option :value="0" disabled>选择已关联证据</option><option v-for="id in receiptEvidence" :key="id" :value="id">#{{ id }} · {{ evidenceName(id) }}</option><option v-if="receipt.evidenceId && !receiptEvidence.includes(receipt.evidenceId)" :value="receipt.evidenceId">#{{ receipt.evidenceId }}（已不在关联范围，请核对）</option></select></label><label class="field">系统 / 渠道（按事项填写）<input v-model.trim="receipt.system" maxlength="160" :disabled="!!busy"></label><button class="button button-secondary" type="button" :disabled="!!busy" @click="draft.receipts.splice(index,1)">移除此用途</button></div><button class="button button-secondary" type="button" :disabled="!!busy || draft.receipts.length>=50" @click="draft.receipts.push({purpose:kindReceiptPurposes[draft.kind][0]!,evidenceId:0,system:''})">添加证据用途</button></div>
      <div class="ai-security-body"><p class="ai-security-note">{{ catalog?.boundary }}</p><div class="ai-security-actions"><button class="button button-primary" :disabled="!!busy || !catalog">{{ busy==='save'?'正在保存…':mode==='create'?'保存办理登记':'保存内容修订' }}</button><span class="table-secondary">保存内容后，再提交独立复核；保存不会执行源端操作。</span></div></div>
    </form>
  </section>
</template>
